# Material docente: idea, ejemplo explicado y decisiones justificadas.
extra_lesson_catalog <- function() list(
  parallel=list(title="Preprocesamiento paralelo / repartir trabajo sin cambiar el an\u00e1lisis",goal="Elegir recursos del equipo y verificar la ejecuci\u00f3n efectiva.",
    meaning=c("Un trabajador es otro proceso local de R. Varios pueden examinar lotes independientes de documentos al mismo tiempo: estimar idiomas, limpiar texto o anotar lemas. Los resultados vuelven a sus posiciones originales. La combinaci\u00f3n de matrices y los indicadores conservan su m\u00e9todo; repartir trabajo no a\u00f1ade documentos ni cambia significados.","Iniciar procesos, cargar modelos y comunicar resultados tambi\u00e9n consume tiempo y memoria. Por eso la casilla habilita paralelismo solo cuando hay volumen suficiente; en un corpus peque\u00f1o puede aparecer Secuencial aunque est\u00e9 marcada. Los trabajadores son locales, compatibles con Windows y se cierran al terminar o interrumpir. Si un trabajador falla, se intenta la v\u00eda secuencial y se registra la recuperaci\u00f3n."),
    example=c("Con 36 res\u00famenes breves, iniciar dos procesos puede costar m\u00e1s que limpiar las palabras: se usa la v\u00eda secuencial. Con miles de textos o suficientes unidades para lematizar, los lotes se reparten. Dos trabajadores no garantizan el doble de velocidad: una parte del trabajo es serial y cada proceso necesita memoria. La tabla muestra qu\u00e9 v\u00eda se utiliz\u00f3 realmente y su tiempo."),
    action=c("Empieza con dos trabajadores si el equipo lo permite. Se deja al menos un n\u00facleo libre y se limita a cuatro; no elijas m\u00e1s por suponer que siempre acelerar\u00e1. Para un port\u00e1til con poca memoria o para resolver un problema, desmarca la casilla o elige uno. Compara tiempos con el mismo corpus y opciones, y verifica que las tablas coinciden. Las decisiones y la ejecuci\u00f3n efectiva se conservan en la descarga.","Los tiempos dependen del equipo, del tama\u00f1o de los textos y de los modelos cargados. Mientras se prepara, espera al resultado antes de cambiar opciones. El indicador de progreso muestra la etapa y el avance entre lotes. La semilla de muestreo y modelos sigue teniendo el mismo significado."),
    sources=c("R / procesos PSOCK y cierre"="https://www.stat.ethz.ch/R-manual/R-devel/library/parallel/html/makeCluster.html")),
  bm25=list(title="TF-IDF y BM25 / dos formas de ponderar vocabulario",
    goal="Elegir una ponderaci\u00f3n por su finalidad y comprobar lo que cambia.",
    meaning=c("Ponderar significa dar a cada t\u00e9rmino un peso para comparar textos. TF-IDF relaciona su uso dentro del texto con su rareza entre textos. BM25 evita que repetir una palabra diez veces aporte diez veces el peso de mencionarla una vez: cada repetici\u00f3n adicional aumenta el peso menos que la anterior. Ese aumento cada vez menor se llama saturaci\u00f3n. El par\u00e1metro de repeticiones, k1, controla cu\u00e1nto siguen aportando las repeticiones; un valor mayor retrasa esa reducci\u00f3n. El par\u00e1metro de longitud, b, controla cu\u00e1nto se ajusta el peso por la longitud del texto: 0 no aplica ese ajuste y 1 lo aplica por completo. La longitud se mide aqu\u00ed en palabras del vocabulario analizado."),
    example=c("Ejemplo de repetici\u00f3n: en textos de longitud media, con k1 = 1,2, el factor de frecuencia vale 1,00 con una menci\u00f3n, 1,38 con dos y 1,77 con cinco. Cinco menciones no multiplican el peso por cinco. Son factores antes de aplicar la rareza de la palabra, no pesos finales.","Ejemplo de longitud: la misma palabra aparece tres veces en un texto de 80 palabras y en otro de 400; la longitud media es 240. Con k1 = 1,2 y b = 0,75, sus factores de frecuencia son 1,83 y 1,38, respectivamente. El texto largo recibe menos peso porque ofrece m\u00e1s oportunidades de repetir. Con b = 0 ambos reciben 1,57. Empezar con k1 = 1,2 y b = 0,75 permite comparar; no garantiza una mejor representaci\u00f3n."),
    action=c("Conserva TF-IDF como primera ejecuci\u00f3n y contrasta BM25 si hay longitudes muy distintas. Revisa grupos y documentos, no solo el mapa. BM25 en esta app pondera vocabulario sin una consulta de b\u00fasqueda; no es un ranking de relevancia validado ni calidad cient\u00edfica. En Preparaci\u00f3n su media usa documentos activos; antes de LSA se aplica al vocabulario retenido. LDA y correspondencias conservan conteos, y ACP conserva su TF-IDF documentado."),
    study=c("BM25 usa aqu\u00ed IDF positiva log(1+(N-df+0,5)/(df+0,5)). N cuenta documentos con vocabulario y df documentos con el t\u00e9rmino. El factor de frecuencia es f(k1+1)/(f+k1(1-b+bL/Lmedio)); f es su conteo y L longitud en tokens del vocabulario analizado. Despu\u00e9s se normaliza para LSA. Es una variante expl\u00edcita, no el IDF original que puede ser negativo."),
    sources=c("Robertson y Zaragoza"="https://doi.org/10.1561/1500000019")),
  seed=list(title="Semilla / repetir no es demostrar estabilidad",
    goal="Distinguir reproducibilidad y sensibilidad.",
    meaning=c("La semilla fija el punto de partida de las operaciones aleatorias. UMAP puede construir coordenadas distintas con otra semilla y LSA aproximada tambi\u00e9n puede variar. HDBSCAN, en cambio, da el mismo resultado al recibir las mismas coordenadas. Una clasificaci\u00f3n repetible todav\u00eda puede depender de par\u00e1metros que has elegido."),
    example=c("Guarda una ejecuci\u00f3n con 2026 y otra con 2027, sin cambiar m\u00e1s decisiones. Si el mapa gira pero los grupos se mantienen, la apariencia no demuestra una clasificaci\u00f3n diferente. Si documentos cambian de grupo, revisa sus textos y las asignaciones: esa diferencia s\u00ed afecta la interpretaci\u00f3n tem\u00e1tica."),
    action=c("En clase usa una semilla para poder repetir el ejemplo. En investigaci\u00f3n contrasta ejecuciones y conserva las discrepancias, sin escoger solo la que confirma tu idea. Las versiones de paquetes tambi\u00e9n forman parte de la reproducibilidad y quedan en la entrega.")),
  ngrams=list(title="N-gramas / qu\u00e9 cuenta cada indicador",
    goal="Elegir entre repetici\u00f3n, cobertura, especificidad y concentraci\u00f3n.",
    meaning=c("Un unigrama es una unidad l\u00e9xica; un bigrama son dos consecutivas; un trigrama, tres. La app cuenta secuencias del texto normalizado sin cruzar puntuaci\u00f3n ni palabras eliminadas. Si lematizas, esas secuencias contienen lemas. Si importas ra\u00edces stemmizadas, los n-gramas estar\u00e1n formados por esas ra\u00edces: no recuperamos autom\u00e1ticamente las palabras originales.", "Apariciones totales cuenta todas las repeticiones. Presencia documental cuenta documentos distintos, una vez por documento aunque haya muchas repeticiones. TF-IDF pondera cu\u00e1nto ocupa la expresi\u00f3n en cada documento y cu\u00e1n rara es entre documentos. Concentraci\u00f3n, calculada como uno menos entrop\u00eda normalizada, resume si sus apariciones se acumulan en pocos documentos o se reparten."),
    example=c("Una expresi\u00f3n aparece diez veces en un solo documento. Otra aparece una vez en diez documentos. Ambas tienen frecuencia diez, pero la primera tiene presencia uno y la segunda diez. La primera est\u00e1 m\u00e1s concentrada; la segunda tiene m\u00e1s cobertura del corpus.", "Si diez documentos aportan expresiones de esa longitud y todas las repeticiones est\u00e1n en uno, la entrop\u00eda es cero y la concentraci\u00f3n uno. Si hay una aparici\u00f3n en cada uno de los diez, la entrop\u00eda normalizada es uno y la concentraci\u00f3n cero. TF-IDF responde otra pregunta: cu\u00e1nto ocupa localmente y qu\u00e9 textos ayuda a distinguir. No sustituye a los otros indicadores."),
    action=c("Empieza por presencia para evitar que una repetici\u00f3n intensa de un \u00fanico texto domine el ranking. Despu\u00e9s consulta frecuencia para saber cu\u00e1ntas apariciones hay y concentraci\u00f3n para ver c\u00f3mo se reparten. Usa TF-IDF si quieres vocabulario distintivo y lee el texto donde aparece. Comparar longitud uno y tres requiere reconocer que no hay el mismo n\u00famero de expresiones posibles.", "Documento activo de longitud n significa que aporta al menos una expresi\u00f3n v\u00e1lida de esa longitud. TF usa el n\u00famero de apariciones de esa expresi\u00f3n dividido por todas las expresiones v\u00e1lidas de longitud n de ese documento. IDF utiliza documentos activos y su media incluye ceros. El porcentaje de presencia y la normalizaci\u00f3n de entrop\u00eda usan todo el corpus preparado."),
    study=c("Los n-gramas se calculan antes del l\u00edmite de vocabulario de modelos, pero despu\u00e9s de filtros de tokens, lemas y categor\u00edas. No son pruebas estad\u00edsticas de colocaci\u00f3n: una expresi\u00f3n de peso alto puede ser ruido, una f\u00f3rmula de escritura o vocabulario espec\u00edfico de un caso.")),
  roles=list(title="Roles en una red / estructura no equivale a liderazgo",
    goal="Interpretar comunidades y centralidades con su alcance real.",
    meaning=c("Una comunidad re\u00fane conexiones relativamente concentradas dentro de un conjunto de nodos. Louvain y Walktrap utilizan criterios distintos para proponer una partici\u00f3n. La posici\u00f3n en pantalla no decide la comunidad. Grado cuenta vecinos; fuerza suma pesos; intermediaci\u00f3n describe participaci\u00f3n en caminos m\u00ednimos de la red analizada."),
    example=c("Una autora puede tener muchos colaboradores de un mismo equipo y mucho grado. Otra puede conectar dos equipos con pocas conexiones y ser una articulaci\u00f3n: al retirarla, una parte se desconecta. Estos dos papeles son distintos y no demuestran prestigio, autoridad ni influencia fuera del corpus."),
    action=c("Consulta los indicadores de conexiones y puentes junto a las centralidades. La tabla Key players / nodos que cubren vecinos distintos elige, paso a paso, el nodo que a\u00f1ade m\u00e1s personas o elementos nuevos a una conexi\u00f3n de distancia, contando tambi\u00e9n el propio nodo. Si dos candidatos comparten vecinos, esos vecinos se cuentan una sola vez. Es una selecci\u00f3n aproximada y no un ranking universal de influencia. Si extraes un subgrafo, sus centralidades se recalculan: no atribuyas al nodo el mismo valor que ten\u00eda en la red completa."),
    sources=c("igraph / comunidades"="https://igraph.org/r/html/latest/cluster_louvain.html")),
  references=list(title="Cobertura y referencias / qu\u00e9 informaci\u00f3n tenemos",
    goal="Distinguir ausencia de datos, citas recibidas y obras citadas.",
    meaning=c("Cobertura indica cu\u00e1ntos documentos tienen un metadato v\u00e1lido. Sin a\u00f1o no podemos situar un registro en el tiempo; sin referencias no podemos estudiar su bibliograf\u00eda; sin citas registradas no conocemos ese conteo. Ausente no significa cero. La primera tabla sirve para decidir qu\u00e9 an\u00e1lisis tienen base suficiente y reconocer sus l\u00edmites.", "Citas recibidas es el n\u00famero comunicado por la base de datos. Referencias citadas son las obras de la bibliograf\u00eda del documento. El primer n\u00famero no permite reconstruir las segundas. La columna CR o Referencias identifica esas obras, separadas como autores y keywords por el delimitador que has elegido."),
    example=c("A y B citan la misma obra: los documentos A y B comparten una referencia y est\u00e1n acoplados. Un documento cita dos obras juntas: esas obras est\u00e1n cocitadas. Las dos redes tienen nodos distintos. Si una obra aparece escrita de dos maneras, el matching exacto puede tratarla como dos referencias; hay que revisar variantes."),
    action=c("Selecciona una tabla y lee su explicaci\u00f3n. El ranking de referencias cuenta documentos citantes por cadena normalizada, no citas recibidas en toda la literatura. La concentraci\u00f3n de fuentes acumula documentos en revistas ordenadas por productividad, sin probar una ley. Las citas relativas comparan con la media del mismo a\u00f1o del corpus, con al menos cinco datos v\u00e1lidos y media positiva; no normalizan por disciplina."),
    sources=c("bibliometrix / citations"="https://rdrr.io/cran/bibliometrix/man/citations.html")),
  coverage=list(title="Cobertura / antes de interpretar una cifra",
    goal="Saber qu\u00e9 registros aportan informaci\u00f3n a cada resultado.",
    meaning=c("La cobertura es la disponibilidad de datos para el c\u00e1lculo. El total preparado dice cu\u00e1ntos documentos estudias; documentos con a\u00f1o, autores, fuente o citas indica cu\u00e1ntos pueden contribuir a ese an\u00e1lisis. Una media calculada con una parte del corpus no representa autom\u00e1ticamente los registros desconocidos."),
    example=c("Hay cien documentos, pero treinta tienen referencias. Una red basada en referencias describe esas bibliograf\u00edas disponibles. No puedes concluir que los otros setenta no citen obras: simplemente no tienes sus referencias. Lo mismo ocurre con cero citas frente a una cita ausente."),
    action=c("Comprueba la cobertura, investiga si los faltantes se concentran en a\u00f1os o fuentes y registra la limitaci\u00f3n. Ampl\u00eda o corrige la exportaci\u00f3n si tu pregunta necesita un metadato ausente. No a\u00f1adas ceros ni rellenes nombres por intuici\u00f3n.")),
  bradford=list(title="Bradford / revistas n\u00facleo y dispersi\u00f3n",
    goal="Saber cu\u00e1ntas revistas re\u00fanen cada tercio de los art\u00edculos y si el reparto se parece al que describe Bradford.",
    meaning=c("Bradford estudia c\u00f3mo se distribuye la literatura entre revistas: unas pocas re\u00fanen muchos art\u00edculos y muchas otras publican pocos. Se ordenan las revistas de m\u00e1s a menos productivas y se forman tres zonas con aproximadamente el mismo n\u00famero de art\u00edculos. La ley dice que cada zona necesita varias veces m\u00e1s revistas que la anterior, con un multiplicador parecido (1 : k : k\u00b2).", "La aplicaci\u00f3n calcula las tres zonas y los multiplicadores en la pesta\u00f1a Leyes bibliom\u00e9tricas. El resultado es descriptivo: dice cu\u00e1nto se parece tu corpus a ese esquema, no demuestra la ley. La curva acumulada de Cobertura y referencias muestra la misma concentraci\u00f3n de forma continua."),
    example=c("Ejemplo ilustrativo con cifras inventadas: 105 revistas publican 240 art\u00edculos. Cinco revistas re\u00fanen los primeros 80, otras 20 re\u00fanen los 80 siguientes y 80 m\u00e1s re\u00fanen los \u00faltimos 80. El n\u00famero de revistas se multiplica por 4 en cada paso (5 : 20 : 80), que es el esquema de Bradford."),
    action=c("Mira cu\u00e1ntas revistas forman el n\u00facleo y si los dos multiplicadores son parecidos. Revisa antes que cada revista tenga un \u00fanico nombre y que los documentos sin revista no distorsionen la lectura. Con menos de nueve revistas la aplicaci\u00f3n no calcula las zonas."),
    reading="Si los dos multiplicadores son parecidos, el reparto se acerca al de Bradford; si difieren mucho, no. Que se parezca no demuestra la ley ni la calidad de las revistas: depende de c\u00f3mo se delimit\u00f3 la b\u00fasqueda.",
    reporting="Escribe lo observado: \u00abLas N revistas del n\u00facleo re\u00fanen el X % de los art\u00edculos; el n\u00famero de fuentes se multiplica por k1 y por k2 en las zonas siguientes\u00bb. Evita \u00abse confirm\u00f3 la ley de Bradford\u00bb; di \u00abel reparto es (o no es) compatible con el esquema de Bradford\u00bb.",
    sources=c("bibliometrix / Bradford"="https://cran.r-project.org/web/packages/bibliometrix/bibliometrix.pdf")),
  lotka=list(title="Lotka / pocos autores producen mucho",
    goal="Saber si la producci\u00f3n de tu corpus se concentra en pocos autores, como describe la ley de Lotka.",
    meaning=c("La ley de Lotka observa que, en muchos campos, la mayor\u00eda de los autores firma un solo trabajo y muy pocos firman muchos. En su forma cl\u00e1sica, los autores con x trabajos son proporcionales a 1/x\u00b2: si 100 autores firman un trabajo, cabe esperar unos 25 con dos y unos 11 con tres. El exponente (2 en la forma cl\u00e1sica) indica con qu\u00e9 rapidez disminuye el n\u00famero de autores al aumentar los trabajos.", "La aplicaci\u00f3n estima el exponente de tu corpus por m\u00e1xima verosimilitud y mide cu\u00e1nto se aparta tu curva de la ajustada con una distancia de Kolmogorov-Smirnov. El resultado es descriptivo."),
    example=c("Ejemplo ilustrativo con cifras inventadas: de 400 autores, 256 firman un trabajo (64 %), 57 firman dos y 23 firman tres. Con el patr\u00f3n cl\u00e1sico se esperar\u00eda un 61,6 % con un trabajo: tu corpus es parecido y el exponente sale cerca de 2."),
    action=c("Mira el porcentaje de autores con un solo trabajo y si los puntos rojos siguen la l\u00ednea. Antes de interpretar, comprueba que cada persona aparezca con un solo nombre (las variantes se cuentan como autores distintos). Con menos de veinte autores, o con menos de tres niveles de productividad, la aplicaci\u00f3n no calcula el ajuste."),
    reading="Un exponente cercano a 2 indica un reparto parecido al cl\u00e1sico. Mayor que 2, a\u00fan m\u00e1s autores de un solo trabajo. Menor que 2, la producci\u00f3n est\u00e1 m\u00e1s repartida entre autores prol\u00edficos. \u00abCompatible\u00bb significa que no se detecta diferencia con el patr\u00f3n, no que la ley est\u00e9 probada; con pocos autores casi cualquier curva resulta compatible.",
    reporting="Escribe lo observado: \u00abDe N autores, el X % firma un \u00fanico trabajo; el exponente de Lotka ajustado es n y la distancia de Kolmogorov-Smirnov es D (referencia R)\u00bb. Evita \u00abse confirm\u00f3 la ley de Lotka\u00bb.",
    sources=c("bibliometrix / Lotka"="https://cran.r-project.org/web/packages/bibliometrix/bibliometrix.pdf")),
  zipf=list(title="Zipf / pocas palabras muy frecuentes",
    goal="Saber si la frecuencia de las palabras de tu corpus se reparte como describe la ley de Zipf.",
    meaning=c("La ley de Zipf dice que la palabra m\u00e1s frecuente aparece aproximadamente el doble que la segunda, el triple que la tercera, y as\u00ed sucesivamente: frecuencia proporcional a 1/rango. Con ejes logar\u00edtmicos eso es una recta de pendiente cercana a \u22121. El exponente es el valor absoluto de esa pendiente.", "La aplicaci\u00f3n ajusta la recta con las palabras que evalu\u00f3 tras limpiar el texto, es decir, sin palabras vac\u00edas y antes de aplicar tu filtro de vocabulario para los modelos."),
    example=c("Ejemplo ilustrativo: si la palabra n.\u00ba 1 aparece 1.000 veces, la n.\u00ba 2 aparecer\u00eda unas 500, la n.\u00ba 10 unas 100 y la n.\u00ba 100 unas 10."),
    action=c("\u00dasala para comprobar si el vocabulario se comporta como un texto natural. Con res\u00famenes cortos o pocos documentos el exponente es poco estable y suele ser menor que 1. Con menos de treinta palabras distintas la aplicaci\u00f3n no calcula el ajuste."),
    reading="Un exponente entre 0,8 y 1,2 con una recta clara se considera cercano al patr\u00f3n de Zipf. Menor que 0,8, el vocabulario est\u00e1 m\u00e1s repartido; mayor que 1,2, unas pocas palabras dominan. Muchas distribuciones distintas dan una recta parecida: el ajuste no prueba la ley.",
    reporting="Escribe lo observado: \u00abEl exponente de Zipf ajustado a N palabras es s (R\u00b2 = r)\u00bb. Indica que se calcul\u00f3 sobre las palabras evaluadas tras la limpieza y evita \u00abse confirm\u00f3 la ley de Zipf\u00bb.",
    sources=c("Zipf / ley de potencias"="https://cran.r-project.org/web/packages/bibliometrix/bibliometrix.pdf")),
  subgraphs=list(title="Subgrafos / estudiar una parte sin perder la red de origen",
    goal="Definir la selecci\u00f3n y recalcular medidas dentro de ella.",
    meaning=c("Un subgrafo conserva algunos nodos y sus conexiones internas. Aqu\u00ed es inducido: una vez elegidos los nodos, se conservan todas las conexiones de la red original entre ellos y sus pesos. Puedes elegir vecindario, comunidad, componente o una lista manual. La red completa permanece disponible.", "Las centralidades y la densidad dependen del conjunto de nodos considerado; por eso se recalculan. Tambi\u00e9n se vuelven a buscar comunidades dentro del subgrafo. Comunidad y grado de origen se conservan para comparar. Los documentos asociados a un nodo y los pesos siguen referidos al corpus de origen: no se han creado nuevos datos."),
    example=c("En A\u2013B\u2013C\u2013D, B tiene dos vecinos. Si eliges A y B, el grado de B dentro del subgrafo pasa a uno, aunque en la red original fuera dos. Un nodo que conectaba zonas distintas puede dejar de parecer intermediario al retirar una de esas zonas. Eso es un cambio de universo de an\u00e1lisis, no una contradicci\u00f3n."),
    action=c("Indica por qu\u00e9 estudias esa zona, extrae y consulta indicadores y nodos antes de concluir. Guardar la selecci\u00f3n y la red de origen permite reproducir. Un subgrafo peque\u00f1o o sin conexiones tambi\u00e9n es un resultado v\u00e1lido; no borres aislados para fabricar una estructura m\u00e1s densa. El ZIP separado contiene datos y un script, y la entrega completa incluye el subgrafo vigente.")),
  temporal=list(title="Evoluci\u00f3n tem\u00e1tica / puntos, curvas y estacionalidad",
    goal="Elegir una representaci\u00f3n temporal compatible con los datos.",
    meaning=c("Las barras cuentan documentos de grupos fijos por a\u00f1o. Las proporciones dividen documentos de un grupo entre todos los documentos del modelo con ese a\u00f1o, incluidos sin asignar. As\u00ed se distingue volumen y peso relativo. La clasificaci\u00f3n se ha estimado con el corpus completo; estas figuras no entrenan un nuevo tema para cada fecha.", "Una spline penalizada resume cambios de forma suave en vez de conectar todos los puntos r\u00edgidamente. Se ajusta un modelo grupo frente al resto con enlace logit y correcci\u00f3n de dispersi\u00f3n. La penalizaci\u00f3n limita curvas excesivamente onduladas. Su validez depende de cobertura, clasificaci\u00f3n, supuestos y residuos; m\u00e1s suavidad no garantiza verdad."),
    example=c("Un grupo pasa de diez a veinte documentos, pero el total del a\u00f1o pasa de veinte a cien. Su volumen se duplica y su peso baja de 50% a 20%. Una curva de proporci\u00f3n cuenta esa segunda historia. Si faltan a\u00f1os, conectar extremos podr\u00eda ocultar una laguna: las l\u00edneas observadas se interrumpen.", "Estacionalidad es una repetici\u00f3n ligada a un ciclo regular, como cada mes o trimestre. Con un \u00fanico dato anual se pierde lo que ocurri\u00f3 en cada estaci\u00f3n. Los a\u00f1os de publicaci\u00f3n pueden describir evoluci\u00f3n, pero no demostrar una estacionalidad mensual; har\u00edan falta fechas suficientemente finas, varios ciclos y cobertura comprobada."),
    action=c("Empieza por puntos y tabla de conteos/denominadores. Ajusta una spline solo si la cobertura satisface las condiciones indicadas y revisa sensibilidad y diagn\u00f3sticos. La banda es puntual y condicional: no integra incertidumbre de la b\u00fasqueda, la clasificaci\u00f3n o una dependencia temporal no modelada. No la uses como prueba de causalidad ni pron\u00f3stico.", "Para cambios del vocabulario puedes consultar palabras del mismo grupo por a\u00f1o; no equivale a estimar que su distribuci\u00f3n tem\u00e1tica evoluciona dentro de un modelo din\u00e1mico. La app no ejecuta estacionalidad con a\u00f1os agregados ni llama DTM a estas curvas."),
    sources=c("mgcv / splines penalizadas"="https://search.r-project.org/CRAN/refmans/mgcv/html/gam.html", "Patrones temporales / Hyndman y Athanasopoulos"="https://otexts.com/fpp3/graphics.html")),
  topic_labels=list(title="Nombrar un tema / una interpretaci\u00f3n que debes justificar",
    goal="Pasar de patrones de palabras a una etiqueta humana verificable.",
    meaning=c("LDA entrega temas numerados y probabilidades de t\u00e9rminos, sin una etiqueta sem\u00e1ntica garantizada. Un LLM no es necesario para calcularlos ni para proponer una primera lectura. El investigador puede nombrarlos examinando vocabulario y documentos, pero debe justificar esa interpretaci\u00f3n."),
    example=c("Un tema tiene hospital, paciente y prevenci\u00f3n. Tras leer res\u00famenes de atenci\u00f3n primaria, puedes proponer Atenci\u00f3n sanitaria. Si otros textos del mismo tema hablan de planificaci\u00f3n urbana o riesgos laborales, prueba una etiqueta m\u00e1s amplia o admite heterogeneidad. No conviene tomar una palabra llamativa como explicaci\u00f3n de todo el tema."),
    action=c("Lee t\u00e9rminos de mayor beta y varios documentos de mayor proporci\u00f3n, adem\u00e1s de casos ambiguos. Anota una etiqueta provisional, una definici\u00f3n y los ID que la apoyan o contradicen. Contrasta con otros temas y, si es posible, otra persona. Si utilizas IA para sugerir nombres, conserva la sugerencia y tu comprobaci\u00f3n: la etiqueta final sigue siendo responsabilidad humana.")),
  lda_time=list(title="LDA y tiempo / prevalencia fija no es modelo din\u00e1mico",
    goal="Distinguir preguntas temporales diferentes.",
    meaning=c("La LDA de esta app se ajusta una vez con el corpus completo. Sus distribuciones de palabras por tema permanecen fijas; despu\u00e9s se agrupan las mezclas de documentos por a\u00f1o para describir prevalencia. Eso permite preguntar cu\u00e1nto participa un tema en los documentos de cada a\u00f1o, sin cambiar su definici\u00f3n dentro del modelo.", "Un modelo din\u00e1mico de temas introduce tiempo en el proceso generativo y permite evoluci\u00f3n de distribuciones tem\u00e1ticas entre per\u00edodos. Existen m\u00e9todos espec\u00edficos, como el de Blei y Lafferty. Ajustar varias LDA por separado tampoco garantiza temas comparables: sus identificadores y distribuciones pueden cambiar y habr\u00eda que alinearlos y validarlos."),
    example=c("Tema 2 mantiene las mismas probabilidades de hospital y escuela en la ejecuci\u00f3n completa. Su proporci\u00f3n media pasa de 20% a 35% entre los documentos de dos a\u00f1os. Es cambio de prevalencia del tema fijo. No demuestra que Tema 2 cambiara internamente de significado o vocabulario entre esos a\u00f1os."),
    action=c("Lee esta figura como descripci\u00f3n de mezclas de documentos con a\u00f1o v\u00e1lido. No conviertas la media en un n\u00famero de art\u00edculos exclusivamente de un tema. Registra cobertura y reconoce cambios de b\u00fasqueda o idioma. La app no implementa un DTM ni presenta esta vista como tal; el an\u00e1lisis din\u00e1mico exige otro modelo y su validaci\u00f3n."),
    sources=c("Blei y Lafferty / Dynamic Topic Models"="https://www.cs.cmu.edu/afs/cs/usr/lafferty/www/pub/dtm.pdf")),
  skills=list(title="Skills / supervisi\u00f3n, autor\u00eda e integridad acad\u00e9mica",
    goal="Usar instrucciones de trabajo sin delegar responsabilidad cient\u00edfica.",
    meaning=c("Una skill es una gu\u00eda reutilizable para organizar una tarea. Estas dos ayudan al investigador a registrar evidencia, revisar afirmaciones y preparar borradores. No son un autor autom\u00e1tico de un paper: la pregunta, el argumento, el m\u00e9todo, la interpretaci\u00f3n y la versi\u00f3n final pertenecen a autores humanos que responden por ellos.", "Cualquier cifra, referencia, interpretaci\u00f3n o texto asistido debe supervisarse exhaustivamente. Un borrador fluido puede contener errores, citas falsas, conclusiones no sostenidas o formulaciones inapropiadas. Las skills exigen verificaci\u00f3n contra CSV completos y fuentes; la asistencia de IA no convierte una afirmaci\u00f3n en evidencia."),
    example=c("Puedes pedir una tabla de afirmaciones con su archivo, columna y denominador antes de redactar. Despu\u00e9s compruebas esa tabla y decides qu\u00e9 resultados sostienen tu argumento. Un revisor asistido puede se\u00f1alar una explicaci\u00f3n alternativa, pero t\u00fa debes comprobarla y decidir si afecta la conclusi\u00f3n. Copiar un texto convincente sin ese examen incumple la finalidad de esta gu\u00eda."),
    action=c("Aplica las skills como apoyo supervisado y conserva comprobaciones y cambios. Revisa cada referencia en su fuente original, cada cifra en los datos y cada afirmaci\u00f3n en su alcance. Declara el uso de IA conforme a instituci\u00f3n y revista, sin atribuirle autor\u00eda ni inventar declaraciones \u00e9ticas. Las herramientas y mecanismos de instalaci\u00f3n var\u00edan: SKILL.md puede instalarse donde se admita o adjuntarse como contexto junto a sus referencias. Nada se env\u00eda ni publica autom\u00e1ticamente."))
)

model_comparison_table <- function(lda=NULL,density=NULL,pca=NULL,ca=NULL,prepared=NULL,pca_axes=c(1L,2L)) {
  row <- function(method,fit,representation,result,caution) data.frame(metodo=method,estado=if(is.null(fit)) "Sin calcular / no vigente" else "Vigente",representacion=representation,
    resultado=if(is.null(fit)) "Calcula el m\u00e9todo para comparar sus resultados" else result,interpretacion=caution)
  out<-rbind(row("LDA",lda,"Conteos / mezcla por unidad",if(!is.null(lda)) paste(lda$params$k,"temas /",lda$units,"unidades /",lda$terms,"t\u00e9rminos"),"Cada documento puede mezclar temas. k es elegido; leer palabras y textos."),
    row("UMAP + HDBSCAN",density,if(is.null(density)) "LSA lexical o vectores importados" else density$representation$type,
      if(!is.null(density)) paste(sum(density$summary$grupo>0),"grupos /",sum(density$assignments$grupo==0),"sin asignar de",nrow(density$assignments)),"Agrupaci\u00f3n por densidad; comparar par\u00e1metros y semillas. El mapa 2D es otra proyecci\u00f3n."),
    row("ACP",pca,"TF-IDF centrado / estandarizaci\u00f3n opcional",if(!is.null(pca)) sprintf("%d documentos / plano %d / %d: %.1f%% de varianza",nrow(pca$documents),pca_axes[1],pca_axes[2],sum(pca$dimensions$porcentaje[pca_axes])),"Varianza y cos\u00b2 del plano; no produce cl\u00fasteres por s\u00ed solo."),
    row("Correspondencias",ca,"Conteos / perfiles chi-cuadrado",if(!is.null(ca)) sprintf("%d unidades / plano %.1f%% de inercia",nrow(ca$units),sum(ca$dimensions$porcentaje[1:2])),"Inercia y cos\u00b2; no comparar su porcentaje como si fuera varianza ACP."))
  ca_documents<-if(is.null(ca))NA_integer_ else length(unique(sub("[_.].*$","",ca$units$unit_id)))
  out$documentos_modelo<-c(if(is.null(lda))NA else nrow(lda$document_topics),if(is.null(density))NA else nrow(density$assignments),if(is.null(pca))NA else nrow(pca$documents),ca_documents)
  out$unidades_modelo<-c(if(is.null(lda))NA else lda$units,if(is.null(density))NA else nrow(density$assignments),if(is.null(pca))NA else nrow(pca$documents),if(is.null(ca))NA else nrow(ca$units))
  out$terminos_modelo<-c(if(is.null(lda))NA else lda$terms,if(is.null(density))NA else density$params$vocabulary_terms %||% NA,if(is.null(pca))NA else nrow(pca$terms),if(is.null(ca))NA else nrow(ca$terms))
  out$cobertura_documentos_pct<-if(is.null(prepared))NA_real_ else 100*out$documentos_modelo/nrow(prepared$documents)
  out$hallazgos<-"Pendiente de calcular"
  out$diagnosticos_observados<-"Pendiente de calcular"
  if(!is.null(lda)){
    out$hallazgos[1]<-paste(vapply(seq_len(nrow(lda$prevalence)),function(i){t<-lda$prevalence$tema[i];sprintf("T%d: %.1f %% (%s)",t,100*lda$prevalence$proporcion_media[i],paste(head(lda$top$termino[lda$top$tema==t],3),collapse=", "))},""),collapse="; ")
    v<-lda$diagnostics$overview$valor;out$diagnosticos_observados[1]<-sprintf("NPMI %.3f; UMass %.3f; diversidad %.1f %% de palabras principales distintas. Diagn\u00f3sticos internos; estabilidad requiere repeticiones.",v[1],v[2],100*v[3])
  }
  if(!is.null(density)){
    d<-density$summary;out$hallazgos[2]<-paste(vapply(seq_len(nrow(d)),function(i)sprintf("%s: %d documentos / %.1f %% (%s)",d$etiqueta[i],d$documentos[i],d$porcentaje[i],d$palabras[i]),""),collapse="; ")
    a<-density$assignments;out$diagnosticos_observados[2]<-paste0(sprintf("Sin asignar: %.1f %%",100*mean(a$grupo==0)),if(any(a$grupo>0))sprintf("; membres\u00eda media de asignados %.3f",mean(a$membresia[a$grupo>0])) else "; no se detectan grupos", ". Membres\u00eda no es probabilidad tem\u00e1tica; estabilidad requiere repeticiones.")
  }
  for(i in 3:4){f<-if(i==3)pca else ca;if(is.null(f))next;d<-if(i==3)pca_plane(f,"terms",pca_axes) else f$terms;axes<-if(i==3)pca_axes else c(1,2)
    out$hallazgos[i]<-paste("Mayores contribuciones del plano:",paste(head(d$termino[order(-(d$contribucion_eje_1+d$contribucion_eje_2))],5),collapse=", "))
    out$diagnosticos_observados[i]<-sprintf("Plano %d / %d: %.1f %% de %s; mediana cos\u00b2 de t\u00e9rminos %.3f. %d de %d ejes evaluados superan su referencia nula del 95 %%.",axes[1],axes[2],sum(f$dimensions$porcentaje[axes]),if(i==3)"varianza" else "inercia",stats::median(d$cos2_plano),sum(f$dimensions$supera_azar %in% TRUE),sum(!is.na(f$dimensions$supera_azar)))
  }
  out[c("metodo","estado","documentos_modelo","cobertura_documentos_pct","unidades_modelo","terminos_modelo","resultado","hallazgos","diagnosticos_observados","representacion","interpretacion")]
}

